import{_ as o,o as a,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0054 — Editor dei disegni: merge delle modifiche, undo, ricarica, libreria e ricerca (M18)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.md","filePath":"adr/0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.md"}'),t={name:"adr/0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.md"};function r(d,e,l,c,s,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0054-—-editor-dei-disegni-merge-delle-modifiche-undo-ricarica-libreria-e-ricerca-m18" tabindex="-1">ADR-0054 — Editor dei disegni: merge delle modifiche, undo, ricarica, libreria e ricerca (M18) <a class="header-anchor" href="#adr-0054-—-editor-dei-disegni-merge-delle-modifiche-undo-ricarica-libreria-e-ricerca-m18" aria-label="Permalink to &quot;ADR-0054 — Editor dei disegni: merge delle modifiche, undo, ricarica, libreria e ricerca (M18)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata il 2026-11-15 (decisione dell&#39;owner); implementata in M18 e rilasciata con la 1.6.0. Emenda <a href="./0010-drawing-and-canvas-details.html">ADR-0010</a> (decisioni 5, 6 e 7) e, per l&#39;auto-export, <a href="./0024-excalidraw-feature-parity.html">ADR-0024</a> (decisione 5)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.6 (2026-11-15): §2.7.1, §2.7.2 (punti 3, 4, 5, 7), §2.7.3, §3.4.3, §3.4.5, §3.4.6 e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.7.1 (anteprima, libreria forme), §2.7.2 (punti 3, 4, 5 e 7), §3.4.3 (stato locale <code>sync.db</code>), §3.4.5 (D-04, tabella delle strategie e flusso di decisione), §3.4.6 (scope di <code>.memobrain/</code>, riga <code>excalidraw-library.json</code>); D-04, D-02; ADR-0038, ADR-0039, ADR-0045</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo puntuale: §3.4.5 (la libreria di forme non segue «LWW per chiave» ma un merge per id) e §3.4.6 (la riga <code>excalidraw-library.json</code> dice che segue i config JSON); §2.7.2 punto 4 (auto-export «dopo ogni salvataggio»); inoltre precisazioni a §2.7.1, §2.7.2 (3, 5 e 7) e §3.4.3. L&#39;elenco puntuale è in «Sezioni dello spec da aggiornare» in fondo</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: <code>go test -race</code> di <code>apps/desktop/internal/{app,sync,drawing,indexer}</code> e <code>shared/go/{merge,pathrules}</code>; <code>task conformance</code>; e2e <code>drawing-lifecycle</code>, <code>drawing-merge</code>, <code>drawing-split</code>, <code>drawing-theme</code>, <code>drawing-library</code>; sync a due dispositivi: <code>TestShapeLibraryMergesByID</code> in <code>task test-desktop-e2e</code>) · workbench web (stesso core in WebAssembly e stessa UI; prove: <code>task test-wasm</code> e gli stessi e2e sul core WASM nel browser) · console: non applicabile · cloud: nessuna modifica, né di API né di schema: il merge resta sul client e il protocollo di sync non cambia. Registro: voci <code>drawing.edit</code>, <code>drawing.embeds</code>, <code>drawing.export</code>, <code>drawing.library</code> di <code>shared/parity/features.yaml</code></td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Una rassegna dell&#39;editor dei disegni (Excalidraw nel fork di ADR-0028) fatta per M18 ha confermato venti debolezze, una delle quali con perdita di dati. Le principali:</p><ul><li><strong>Perdita di dati.</strong> Se un file <code>.excalidraw</code> diventava invalido fuori dall&#39;app (un altro programma, una sincronizzazione interrotta), l&#39;editor lo teneva come «versione letta» e il salvataggio successivo lo sovrascriveva con la scena in memoria.</li><li><strong>Modifiche non salvate contro una versione nuova.</strong> Con modifiche non ancora scritte, ogni versione nuova del file (la sincronizzazione, l&#39;altro pannello dello stesso disegno) apriva il banner di conflitto e obbligava a scegliere; con il merge a tre vie già disponibile in <code>shared/go/merge</code> e usato dalla sincronizzazione.</li><li><strong>Annulla.</strong> <code>updateScene</code> senza <code>captureUpdate</code> esplicito poteva trasformare in passo di annullamento una ricarica esterna, o spezzare in più passi un&#39;azione.</li><li><strong>Costi a ogni modifica.</strong> La scena veniva serializzata a ogni <code>onChange</code> (anche per selezione e scroll), <code>onChange</code> e <code>initialData</code> cambiavano identità a ogni render, l&#39;auto-export disegnava PNG e SVG a ogni salvataggio, e ogni embed rileggeva il disegno intero (megabyte, con le immagini) solo per calcolarne l&#39;hash e trovare l&#39;anteprima in cache.</li><li><strong>Cache e tema.</strong> <code>.clarae/cache/drawings/</code> non veniva mai ripulita, gli embed erano sempre chiari e il tema «Sistema» non seguiva il sistema operativo a caldo.</li><li><strong>Libreria di forme.</strong> Era un file letto una volta per editor e sincronizzato come ogni file di impostazioni, cioè con «ultimo scrittore vince» sulla chiave <code>libraryItems</code>: le forme aggiunte da un dispositivo sparivano se un altro scriveva dopo.</li><li><strong>Ricerca.</strong> Il testo indicizzato di un elemento era <code>text</code>, con gli a capo automatici inseriti da Excalidraw: una parola spezzata su due righe non si trovava. Il TeX delle formule non era indicizzato.</li></ul><p>Vincoli: il merge è sempre sul client e il server non interpreta il contenuto (nessuna operazione di API nuova); D-04 garantisce il merge multi-utente solo per i <code>.md</code>; D-02 fa dei vault privati un vault di un solo utente; il core è lo stesso su desktop e nel browser (ADR-0030), quindi ogni logica nuova sta nel core Go, una volta.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-un-file-invalido-non-si-sovrascrive" tabindex="-1">1. Un file invalido non si sovrascrive <a class="header-anchor" href="#_1-un-file-invalido-non-si-sovrascrive" aria-label="Permalink to &quot;1. Un file invalido non si sovrascrive&quot;">​</a></h3><p><code>useNoteDocument</code> (<code>packages/workbench/src/editor/useNoteDocument.ts</code>) accetta l&#39;opzione <code>accept(content)</code>. Una versione letta dopo il primo caricamento che non la soddisfa <strong>non viene adottata</strong>: l&#39;hash resta quello del testo mostrato, quindi il salvataggio successivo non può scrivere sopra un file che l&#39;editor non ha mai visto; il documento passa a <code>save: &#39;conflict&#39;</code> con il nuovo campo <code>rejected: true</code>. Il disegno passa <code>isScene</code> (<code>parseScene</code> non deve fallire). Il banner dice «Il file su disco non è più un disegno valido…» e offre <strong>solo «Sovrascrivi»</strong> (non c&#39;è nulla da ricaricare né da tenere accanto). Quando il file torna valido e non ci sono modifiche non salvate, la ricarica lo mostra e lo stato rientra da solo. L&#39;opzione è usata dal solo disegno; note e lavagne non cambiano.</p><h3 id="_2-annulla-captureupdate-esplicito" tabindex="-1">2. Annulla: <code>captureUpdate</code> esplicito <a class="header-anchor" href="#_2-annulla-captureupdate-esplicito" aria-label="Permalink to &quot;2. Annulla: `captureUpdate` esplicito&quot;">​</a></h3><p>Ogni <code>updateScene</code> dell&#39;editor dichiara <code>captureUpdate</code>: <code>NEVER</code> per ciò che arriva da fuori (ricarica esterna, merge) e per lo spostamento della vista della mini-mappa; <code>IMMEDIATELY</code> per le azioni che cambiano elementi, così <strong>un&#39;azione è un passo di annullamento</strong>. Una modifica di un altro non entra mai nella cronologia di questo editor.</p><h3 id="_3-ricarica-esterna-e-costo-del-salvataggio" tabindex="-1">3. Ricarica esterna e costo del salvataggio <a class="header-anchor" href="#_3-ricarica-esterna-e-costo-del-salvataggio" aria-label="Permalink to &quot;3. Ricarica esterna e costo del salvataggio&quot;">​</a></h3><ul><li>La ricarica applica anche le chiavi di documento di <code>appState</code> (<code>viewBackgroundColor</code>, <code>gridSize</code>, <code>gridStep</code>, <code>gridModeEnabled</code>, <code>lockedMultiSelections</code>: <code>drawing/externalReload.ts</code>, <code>documentAppState</code>) e mai scroll, zoom, selezione o strumento in mano; ripubblica i frame dello Slideshow; aggiorna la firma di scena, perché il cambiamento che Excalidraw riporta per ciò che ha appena ricevuto non è una modifica dell&#39;utente e <strong>non riscrive il file</strong>.</li><li>La scena si serializza solo al salvataggio: <code>doc.edit</code> riceve una funzione, e le chiavi di primo livello del file diverse da quelle di Excalidraw si aggiungono per giunzione di testo (<code>drawing/serialize.ts</code>, <code>appendRootKeys</code>) invece che rileggendo megabyte di base64. La firma di scena (<code>sceneSignature</code>) è un hash scorrevole di id e versioni degli elementi, non l&#39;elenco scritto per esteso. <code>onChange</code> e <code>initialData</code> hanno identità stabile.</li></ul><h3 id="_4-merge-delle-modifiche-non-salvate-vaultapi-mergeedit" tabindex="-1">4. Merge delle modifiche non salvate: <code>VaultAPI.MergeEdit</code> <a class="header-anchor" href="#_4-merge-delle-modifiche-non-salvate-vaultapi-mergeedit" aria-label="Permalink to &quot;4. Merge delle modifiche non salvate: `VaultAPI.MergeEdit`&quot;">​</a></h3><p>Nuovo binding <code>VaultAPI.MergeEdit(vaultID, relPath, base, ours, theirs) → { strategy, merged, clean }</code> (<code>apps/desktop/internal/app/bindings_merge.go</code>; nel browser è nel core WASM e in <code>web/src/workbench/core.gen.ts</code>):</p><ul><li><strong>Solo calcolo:</strong> non legge né scrive file. <code>base</code> è il testo da cui partono le modifiche, <code>ours</code> il testo dell&#39;editor, <code>theirs</code> la versione ora su disco.</li><li><strong>Stesso codice e stessa tabella della sincronizzazione:</strong> la strategia è <code>merge.Decide(syncproto.KindOf(path), sameAuthor, modify, modify)</code>; poi <code>merge.Markdown</code>, <code>merge.Excalidraw</code> o <code>merge.Canvas</code>. <code>clean</code> è vero solo se il merge non lascia scelte. Non è un errore, ma <code>clean: false</code> e <code>merged</code> vuoto, quando: ci sono hunk in conflitto (nota), il tipo non si fonde mai (strategia diversa dalle tre), l&#39;autore non è quello dell&#39;utente su un vault condiviso (D-04, punto 5), il testo non si analizza (<code>strategy: conflict-copy</code>, come farebbe la sync).</li><li><strong>Dentro <code>useNoteDocument</code></strong> l&#39;opzione <code>merge(base, ours, theirs)</code>: quando arriva una versione nuova e ci sono modifiche non salvate, si prova il merge. Se riesce, il testo fuso diventa quello dell&#39;editor, l&#39;hash diventa quello di <code>theirs</code> e il testo si salva sopra <code>theirs</code> dopo il normale ritardo; se una scrittura è rifiutata perché il file è cambiato prima dell&#39;evento, si rifà lo stesso merge. Se non si può, si passa al banner come prima. La scena fusa <strong>non entra nell&#39;annulla</strong> (punto 2).</li><li><strong>Mai sotto un gesto:</strong> il merge sostituisce la scena a schermo, quindi aspetta che non ci sia un gesto in corso (testo in modifica, forma o linea in disegno, trascinamento, ridimensionamento, rotazione, selezione a riquadro: <code>drawing/gesture.ts</code>), fino a <code>MERGE_WAIT_MS</code> = 20 s; dopo, lascia la scelta all&#39;utente con il banner. Un file ridotto a testo vuoto non si fonde.</li><li>Oggi chiama il binding solo <code>DrawingEditor</code>. Il binding sa fondere anche <code>.md</code>, <code>.canvas</code> e <code>.base</code> (stessa strategia della sync), ma note e lavagne tengono il loro flusso con il banner: estenderlo è una scelta separata.</li></ul><h3 id="_5-regola-d-04-nell-editor-l-autore-della-revisione-di-testa-in-sync-db" tabindex="-1">5. Regola D-04 nell&#39;editor: l&#39;autore della revisione di testa in <code>sync.db</code> <a class="header-anchor" href="#_5-regola-d-04-nell-editor-l-autore-della-revisione-di-testa-in-sync-db" aria-label="Permalink to &quot;5. Regola D-04 nell&#39;editor: l&#39;autore della revisione di testa in `sync.db`&quot;">​</a></h3><p>Per decidere se la versione su disco è «dello stesso utente», l&#39;editor non ha il cambio in arrivo, ha solo il file. Quindi <code>sync.db</code> registra l&#39;autore della revisione di cui una riga contiene il contenuto: colonna <code>sync_files.head_author TEXT NOT NULL DEFAULT &#39;&#39;</code> (migrazione <code>apps/desktop/internal/store/migrations/sync/0004_head_author.sql</code>; <code>Down</code> la toglie). Si valorizza con l&#39;autore del cambio quando il pull, una risoluzione o una fusione portano contenuto, con l&#39;utente dell&#39;account quando il commit è nostro; si azzera quando il contenuto non ha un autore noto (bootstrap, <code>republish</code> con contenuto diverso, <code>reupload</code>, rifiuto del server); un solo spostamento di path lo conserva.</p><p><code>Manager.SameAuthorOnDisk(ctx, localID, path, diskHash)</code> (<code>apps/desktop/internal/sync/manager_author.go</code>) risponde così:</p><table tabindex="0"><thead><tr><th>Caso</th><th>Risposta</th></tr></thead><tbody><tr><td>vault non collegato, o privato (un solo autore, D-02)</td><td>vero</td></tr><tr><td>file che la sync non ha mai visto</td><td>vero (scritto qui)</td></tr><tr><td>contenuto su disco diverso da quello che la riga ha visto (scritto qui: altro pannello, altra app, ripristino)</td><td>vero</td></tr><tr><td>stato <code>local_new</code>, <code>local_modified</code>, spostato con modifiche</td><td>vero (contenuto nostro)</td></tr><tr><td>contenuto del server (<code>synced</code>, spostato senza modifiche)</td><td>vero solo se <code>head_author</code> è l&#39;account del vault</td></tr><tr><td><code>conflict</code>, <code>head_author</code> vuoto, errore di lettura di <code>sync.db</code></td><td>falso (cammino prudente: banner)</td></tr></tbody></table><p><strong>Limite dichiarato:</strong> le righe che esistevano prima della migrazione, e quelle adottate da un bootstrap, non hanno autore e contano come «altro autore». Su un vault condiviso, un disegno già sincronizzato prima della 1.6 mostra il banner invece del merge, la prima volta che arriva una versione nuova con modifiche non salvate, finché un pull o un commit non riscrive la riga. Su un vault personale non collegato o privato il merge non ha questo limite. Il merge dell&#39;editor è quindi <strong>più prudente</strong> della sincronizzazione, che conosce l&#39;autore del cambio in arrivo.</p><h3 id="_6-«tieni-entrambe»" tabindex="-1">6. «Tieni entrambe» <a class="header-anchor" href="#_6-«tieni-entrambe»" aria-label="Permalink to &quot;6. «Tieni entrambe»&quot;">​</a></h3><p>Il banner di conflitto ha una terza scelta oltre a <em>Ricarica</em> e <em>Sovrascrivi</em>: <code>NoteDocument.keepBoth()</code> ferma il salvataggio in attesa, salva il testo dell&#39;editor in una copia accanto al file (lo stesso meccanismo di salvataggio di emergenza usato per le modifiche che non si possono scrivere), ricarica il file e dice dove sta la copia («La tua versione del disegno è in una copia accanto al file: …»). Non c&#39;è quando il file è invalido (punto 1).</p><h3 id="_7-due-pannelli-sullo-stesso-disegno" tabindex="-1">7. Due pannelli sullo stesso disegno <a class="header-anchor" href="#_7-due-pannelli-sullo-stesso-disegno" aria-label="Permalink to &quot;7. Due pannelli sullo stesso disegno&quot;">​</a></h3><p>Un disegno aperto in due pannelli ha due editor. <code>getSceneController()</code> sceglie quello del pannello a fuoco (<code>paneId()</code> contro <code>layout.activePane</code>), poi quello del disegno della scheda attiva, poi l&#39;ultimo registrato. Lo store dello Slideshow (<code>drawing/slidesStore.ts</code>) ha un <strong>proprietario</strong> (<code>owner</code>, l&#39;id dell&#39;editor): lo prende chi pubblica quando nessuno lo ha, o quando è a fuoco, e quando un pannello lascia il disegno i frame dell&#39;altro restano nella scheda. Drop e dialoghi vanno all&#39;editor da cui partono.</p><h3 id="_8-auto-export-ritardato-emenda-adr-0024-decisione-5" tabindex="-1">8. Auto-export ritardato (emenda ADR-0024, decisione 5) <a class="header-anchor" href="#_8-auto-export-ritardato-emenda-adr-0024-decisione-5" aria-label="Permalink to &quot;8. Auto-export ritardato (emenda ADR-0024, decisione 5)&quot;">​</a></h3><p>L&#39;esportazione automatica non parte a ogni salvataggio ma <strong>15 s dopo l&#39;ultimo</strong> (<code>AUTO_EXPORT_QUIET_MS</code>, <code>drawing/export/autoExport.ts</code>), e subito alla chiusura del disegno, del vault, al cambio di workspace e all&#39;uscita (<code>registerNoteFlusher</code>). Lavora su una chiave (scena e impostazioni di export): una chiave già esportata non si ripete, e tornare a una scena già esportata (un annulla) annulla l&#39;attesa; i lavori vanno in coda uno alla volta; un lavoro fallito si riprova al salvataggio successivo.</p><h3 id="_9-anteprime-drawingapi-preview-e-varianti-per-tema-emenda-adr-0010-decisione-5" tabindex="-1">9. Anteprime: <code>DrawingAPI.Preview</code> e varianti per tema (emenda ADR-0010, decisione 5) <a class="header-anchor" href="#_9-anteprime-drawingapi-preview-e-varianti-per-tema-emenda-adr-0010-decisione-5" aria-label="Permalink to &quot;9. Anteprime: `DrawingAPI.Preview` e varianti per tema (emenda ADR-0010, decisione 5)&quot;">​</a></h3><ul><li><code>DrawingAPI.Preview(vaultID, relPath, variant) → { hash, svg }</code>: il core calcola l&#39;hash del file <strong>a flusso</strong> (<code>FS.HashFile</code>, senza caricarlo) e restituisce l&#39;SVG in cache per quell&#39;hash e variante, vuoto se non c&#39;è. Un embed con anteprima in cache non rilegge il disegno. <code>variant</code> è <code>&quot;&quot;</code> (chiaro) o <code>&quot;dark&quot;</code>; il percorso è <code>.clarae/cache/drawings/&lt;hash&gt;.svg</code> o <code>&lt;hash&gt;.dark.svg</code>; il file deve essere un <code>.excalidraw</code>.</li><li><code>DrawingAPI.SavePreview(vaultID, hash, variant, svg)</code> prende la variante (limiti invariati: 64 esadecimali, 4 MB, <code>&lt;svg</code> e niente <code>&lt;script</code>). <strong><code>DrawingAPI.ReadPreview</code> è rimosso.</strong></li><li>Lato UI (<code>drawing/preview.ts</code>): gli embed che chiedono lo stesso disegno, parte, variante e versione nello stesso momento <strong>condividono lettura e resa</strong>; solo i disegni interi usano la cache su disco (le parti usano quella in memoria, come prima). Con il tema scuro l&#39;embed mostra la versione scura (<code>exportWithDarkMode</code>) e passa dall&#39;una all&#39;altra al cambio di tema; stampa ed esportazione della nota usano sempre la chiara.</li><li>Il tema «Sistema» segue il sistema operativo a caldo (<code>app/theme.ts</code>, <code>watchTheme</code>/<code>currentTheme</code>; <code>app/useTheme.ts</code>).</li></ul><h3 id="_10-potatura-della-cache-delle-anteprime" tabindex="-1">10. Potatura della cache delle anteprime <a class="header-anchor" href="#_10-potatura-della-cache-delle-anteprime" aria-label="Permalink to &quot;10. Potatura della cache delle anteprime&quot;">​</a></h3><p>All&#39;apertura del vault, <strong>dopo</strong> che l&#39;indice è allineato al disco (<code>apps/desktop/internal/app/drawing_cache.go</code>), si tolgono da <code>.clarae/cache/drawings/</code> i file <code>&lt;hash&gt;.svg</code> e <code>&lt;hash&gt;.dark.svg</code> il cui hash non è quello corrente di nessun disegno dell&#39;indice e che hanno più di 10 minuti (<code>drawingCacheMinAge</code>, per non toccare l&#39;anteprima di un salvataggio appena fatto che il watcher non ha ancora indicizzato). Si guarda solo il nome (<code>^[0-9a-f]{64}(\\.dark)?\\.svg$</code>); gli altri file restano. È a massimo sforzo (la cache è derivata e locale): un errore finisce nel log, non blocca l&#39;apertura. L&#39;ordine conta: la migrazione dell&#39;indice del punto 12 azzera gli hash finché la passata completa non li ripristina. <code>FS.ListFiles</code> elenca una cartella senza applicare le regole di esclusione di <code>Walk</code>.</p><h3 id="_11-libreria-di-forme-store-condiviso-e-merge-per-id-devia-da-§3-4-5-e-§3-4-6" tabindex="-1">11. Libreria di forme: store condiviso e merge per id (devia da §3.4.5 e §3.4.6) <a class="header-anchor" href="#_11-libreria-di-forme-store-condiviso-e-merge-per-id-devia-da-§3-4-5-e-§3-4-6" aria-label="Permalink to &quot;11. Libreria di forme: store condiviso e merge per id (devia da §3.4.5 e §3.4.6)&quot;">​</a></h3><ul><li><strong>Store</strong> (<code>drawing/library/store.ts</code>): una libreria per vault, condivisa da tutti gli editor aperti (una forma aggiunta in un pannello compare subito negli altri); le modifiche si scrivono con un ritardo di 800 ms (<code>LIBRARY_WRITE_MS</code>) e subito alla chiusura; si ricarica quando la sincronizzazione o un altro programma cambiano il file (<code>isLibraryPath</code>, sotto il nome corrente o quello della 1.x della cartella di configurazione).</li><li><strong>Sync: strategia nuova <code>library-by-id</code></strong> (<code>merge.StrategyLibraryByID</code>, <code>merge.LibraryByID</code>). <code>merge.DecideByPath(path, kind, sameAuthor, ours, theirs)</code> è <code>Decide</code> con una eccezione: se la strategia è <code>config-lww</code> e <code>pathrules.IsShapeLibrary(path)</code> (il file <code>excalidraw-library.json</code> nella cartella di configurazione, sotto uno dei due nomi; non in sottocartelle né alla radice), si usa il merge per id. Il motore di sync (<code>sync/resolve.go</code>) chiama <code>DecideByPath</code>. Regole, a tre vie sugli elementi di <code>libraryItems</code> per <code>id</code>: <ul><li>una forma aggiunta da un lato resta;</li><li>una forma tolta da un lato e lasciata com&#39;era dall&#39;altro è tolta;</li><li>una forma tolta da un lato e <strong>modificata</strong> dall&#39;altro resta, con la modifica (nulla si perde in silenzio);</li><li>una forma modificata da entrambi prende la versione del lato più recente (come le chiavi di <code>ConfigLWW</code>); l&#39;altra resta nello storico del server;</li><li>senza base (storico potato) le due librerie si <strong>uniscono</strong>;</li><li>l&#39;ordine è quello di <code>ours</code>, poi le forme nuove di <code>theirs</code> nel loro ordine; le altre chiavi di primo livello si fondono come <code>ConfigLWW</code>.</li></ul></li><li><strong>Non produce mai una copia di conflitto</strong>, salvo un file che non si legge (JSON non valido, <code>libraryItems</code> che non è un elenco, una forma senza <code>id</code>): <code>LibraryByID</code> restituisce un errore e la sync ricade sulla copia di conflitto, come per ogni altro file illeggibile.</li><li>Prove: 13 fixture <code>shared/conformance/merge/library-*</code> (<code>kind: &quot;library&quot;</code> nel <code>meta.json</code>, eseguite da <code>shared/go/merge/merge_test.go</code>), <code>TestDecideByPathGivesTheShapeLibraryItsOwnStrategy</code>, <code>TestLibraryByIDNeverDropsAShapeSomeoneChanged</code> (proprietà), <code>TestShapeLibraryMergesByID</code> (due dispositivi contro il cloud).</li></ul><h3 id="_12-ricerca-nei-disegni-originaltext-e-tex-emenda-adr-0010-decisione-7" tabindex="-1">12. Ricerca nei disegni: <code>originalText</code> e TeX (emenda ADR-0010, decisione 7) <a class="header-anchor" href="#_12-ricerca-nei-disegni-originaltext-e-tex-emenda-adr-0010-decisione-7" aria-label="Permalink to &quot;12. Ricerca nei disegni: `originalText` e TeX (emenda ADR-0010, decisione 7)&quot;">​</a></h3><p><code>internal/drawing</code> indicizza di un elemento <code>text</code> il testo <strong>come lo ha scritto l&#39;utente</strong> (<code>originalText</code>; se manca, <code>text</code>: i file di altri strumenti) e, per un elemento che è una formula, il suo TeX (<code>customData.clarae</code> con <code>kind == &quot;latex&quot;</code> e <code>latex</code>; per i file della 1.x vale ancora <code>customData.memobrain</code>, e la chiave corrente vince). Il TeX entra nel testo cercabile, non nei link. Per questo la migrazione dell&#39;indice <code>apps/desktop/internal/store/migrations/index/0005_reindex_drawings.sql</code> marca le righe dei disegni come scadute (<code>mtime_ns = 0</code>, <code>hash = &#39;&#39;</code>): la prima passata completa dopo l&#39;aggiornamento rianalizza <strong>una volta</strong> ogni disegno e riscrive le due colonne. <code>Down</code> non fa nulla (l&#39;indice è derivato).</p><h3 id="_13-soglie-di-dimensione" tabindex="-1">13. Soglie di dimensione <a class="header-anchor" href="#_13-soglie-di-dimensione" aria-label="Permalink to &quot;13. Soglie di dimensione&quot;">​</a></h3><p>Sopra <strong>8 MB</strong> un disegno non è più indicizzato (solo nome e percorso: <code>maxParseBytes</code>, <code>apps/desktop/internal/indexer/indexer.go</code>, invariato) e sopra <strong>10 MB</strong> si avvisa che è lento (<code>drawing.MaxSize</code>). L&#39;editor ora misura entrambe le soglie <strong>in byte del file salvato</strong> (<code>sizeWarning</code>, <code>drawing/scene.ts</code>), con due avvisi diversi («non più ricercabile» e «lento»), non in caratteri come prima.</p><h3 id="_14-i-tombstone-degli-elementi-cancellati-non-si-potano" tabindex="-1">14. I tombstone degli elementi cancellati non si potano <a class="header-anchor" href="#_14-i-tombstone-degli-elementi-cancellati-non-si-potano" aria-label="Permalink to &quot;14. I tombstone degli elementi cancellati non si potano&quot;">​</a></h3><p>Un elemento cancellato resta nel file con <code>isDeleted</code> (il salvataggio scrive <code>getSceneElementsIncludingDeleted</code>) e <strong>non si pota mai</strong>, né in editor, né in sync, né in un&#39;azione di manutenzione. Nel merge per id di §3.4.5 (<code>merge.Excalidraw</code>: «elementi cancellati rispettati») un tombstone potato lascerebbe all&#39;altro lato la sua copia viva, che <strong>ricomparirebbe</strong> al merge successivo. Il costo è un file che cresce con le cancellazioni, che le soglie del punto 13 rendono visibile.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Reimplementare il merge in TypeScript nell&#39;editor</strong> — scartata: due implementazioni dello stesso merge divergono (è lo stesso motivo per cui i parser hanno fixture condivise). <code>MergeEdit</code> usa <code>shared/go/merge</code>, quindi la sync e l&#39;editor decidono allo stesso modo sul desktop e nel browser.</li><li><strong>Banner sempre, come prima</strong> — scartata: ogni sincronizzazione con modifiche in corso chiedeva una scelta tra due versioni di un file grande, con rischio di sceglierne male.</li><li><strong>Merge tra autori diversi anche nell&#39;editor</strong> — scartata: D-04 lo garantisce solo per i <code>.md</code>; un disegno di un altro utente su un vault condiviso resta una scelta dell&#39;utente.</li><li><strong>Chiedere l&#39;autore al cloud, o dedurlo dalla cronologia</strong> — scartata: servirebbe la rete (il disegno si modifica offline) e una chiamata nuova; l&#39;informazione arriva già con il cambio che la sync applica, e <code>sync.db</code> è il posto dove si tiene lo stato di ogni file.</li><li><strong>Potare i tombstone per contenere la dimensione</strong> — scartata (punto 14).</li><li><strong>Mantenere «ultimo scrittore vince» per la libreria</strong> — scartata: <code>libraryItems</code> è una sola chiave, quindi le forme aggiunte da un dispositivo si perderebbero. <strong>Una libreria con un file per forma</strong> — scartata: cambierebbe il formato <code>excalidrawlib</code> e la compatibilità con gli strumenti che lo leggono.</li><li><strong>Auto-export a ogni salvataggio, con soglia di dimensione</strong> — scartata: il costo è sul thread principale e non dipende solo dalla dimensione; la quiete di 15 s lo toglie dal lavoro in corso senza perdere nulla, perché alla chiusura si esporta subito.</li><li><strong>Hash dell&#39;anteprima calcolato nel frontend (<code>ReadPreview(hash)</code>)</strong> — scartata: per avere l&#39;hash il frontend doveva leggere il file intero.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Nessuna perdita</strong> per un file reso invalido dall&#39;esterno, e per il caso comune (sync mentre si disegna) nessuna scelta manuale. «Annulla» riguarda solo ciò che l&#39;utente ha fatto.</li><li><strong>Compatibilità e aggiornamento.</strong> Due migrazioni locali: <code>sync.db</code> (colonna <code>head_author</code>) e <code>index.db</code> (rianalisi dei disegni al primo avvio, più lunga con molti disegni grandi); nessuna migrazione del cloud, nessuna operazione di API cambiata. I binding del core cambiano (<code>VaultAPI.MergeEdit</code> nuovo; <code>DrawingAPI.Preview</code> al posto di <code>ReadPreview</code>; <code>SavePreview</code> con la variante): desktop e web usano la stessa build, quindi non esistono combinazioni miste. Tornare alla 1.5 sullo stesso dispositivo non è stato provato.</li><li><strong>Prudenza provvisoria sui vault condivisi</strong> (punto 5): finché le righe non hanno un autore, un disegno condiviso mostra il banner dove la sync avrebbe fuso.</li><li><strong>Il merge aspetta</strong> fino a 20 s la fine di un gesto: chi tiene un gesto più a lungo vede il banner.</li><li><strong>Il file di un disegno cresce con le cancellazioni</strong> (punto 14). Le soglie di 8 e 10 MB avvisano.</li><li><strong>Due fonti di verità sulle soglie</strong> (<code>maxParseBytes</code> in Go e <code>DRAWING_SEARCH_BYTES</code> in TypeScript): vanno tenute uguali a mano.</li><li><strong>Fuori da questo ADR:</strong> il merge nell&#39;editor di note, lavagne e basi (punto 4) e una release di rimozione per la lettura dei disegni della 1.x (ADR-0052).</li><li><strong>Da rivedere</strong> dopo prove su due dispositivi reali con utenti diversi su un vault condiviso e su una WebView reale (gli e2e usano Chromium con i binding simulati e il core WASM).</li></ul><h2 id="sezioni-dello-spec-da-aggiornare" tabindex="-1">Sezioni dello spec da aggiornare <a class="header-anchor" href="#sezioni-dello-spec-da-aggiornare" aria-label="Permalink to &quot;Sezioni dello spec da aggiornare&quot;">​</a></h2><p>Recepite in <code>Specifications.md</code> v1.6 (2026-11-15), una per una come nell&#39;elenco. Due punti della decisione non sono nell&#39;elenco, e quindi non sono riportati nello spec: i due pannelli sullo stesso disegno (punto 7) e le soglie di 8 e 10 MB misurate in byte (punto 13).</p><table tabindex="0"><thead><tr><th>Sezione</th><th>Cosa cambia</th></tr></thead><tbody><tr><td>§3.4.5, tabella delle strategie</td><td>Nuova riga «Libreria forme (<code>excalidraw-library.json</code>)»: merge per <code>id</code> della forma, mai conflict copy salvo file illeggibile; la riga «Config JSON» diventa «eccetto la libreria di forme». Nel flusso di decisione il ramo <code>config JSON</code> si divide</td></tr><tr><td>§3.4.5, «Ambito della collaborazione (D-04)»</td><td>Precisare che le stesse regole valgono per il merge delle modifiche non salvate in un disegno aperto, e che l&#39;autore della revisione di testa viene da <code>sync.db</code></td></tr><tr><td>§3.4.3, <code>sync_files</code></td><td>Aggiungere la colonna <code>head_author</code> (autore della revisione di cui la riga ha il contenuto; vuoto se non noto)</td></tr><tr><td>§3.4.6, riga <code>excalidraw-library.json</code></td><td>Togliere «segue la risoluzione dei config JSON» per questo file: si fonde per id</td></tr><tr><td>§2.7.1, riga «Libreria forme»</td><td>Una libreria per vault condivisa dagli editor, con merge per id</td></tr><tr><td>§2.7.1, riga «Anteprima»</td><td>Cache <code>&lt;hash&gt;.svg</code> e <code>&lt;hash&gt;.dark.svg</code>; <code>DrawingAPI.Preview</code> e <code>SavePreview</code> con variante (non più <code>ReadPreview</code>); potatura all&#39;apertura del vault</td></tr><tr><td>§2.7.2, punto 3</td><td>Il salvataggio serializza la scena solo al momento di scrivere; un file invalido non si sovrascrive; modifica esterna con modifiche non salvate: merge nell&#39;editor, «Tieni entrambe»</td></tr><tr><td>§2.7.2, punto 4</td><td>Auto-export 15 s dopo l&#39;ultimo salvataggio e alla chiusura, non «dopo ogni salvataggio»</td></tr><tr><td>§2.7.2, punto 5</td><td>Il tema «Sistema» segue il sistema operativo; gli embed seguono il tema</td></tr><tr><td>§2.7.2, punto 7</td><td>Ricerca: testo come scritto dall&#39;utente (<code>originalText</code>) e TeX delle formule</td></tr><tr><td>§2.7.3 / §3.4.5</td><td>Nota: i tombstone degli elementi cancellati non si potano</td></tr></tbody></table>',46)])])}const m=o(t,[["render",r]]);export{p as __pageData,m as default};
